<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code (with manual adjustments).

namespace Tests\Offer\Action\Query;

use Module\Customer\Action\Query\GetCurrentCustomerStoreIdQry;
use Module\Offer\Action\Enum\QuantityLevelEnum;
use Module\Offer\Action\Query\GetOfferDetailsQry;
use Module\Offer\Model\Offer;
use Module\Offer\Model\OfferRepository;
use Module\Product\Action\Dto\ProductDetailsDto;
use Module\Product\Action\Query\GetProductDetailsQry;
use Module\Shared\Exception\AppValidationException;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Tests\IntegrationTestCase;

class GetOfferDetailsQryTest extends IntegrationTestCase
{
    private const int STORE_ID = 10;

    private GetOfferDetailsQry $sut;

    private OfferRepository $offerRepository;

    public function setUp(): void
    {
        parent::setUp();

        $this->offerRepository = $this->container->get(OfferRepository::class);

        $getCurrentCustomerStoreIdQry = $this->createStub(GetCurrentCustomerStoreIdQry::class);
        $getCurrentCustomerStoreIdQry->method('handle')->willReturn(self::STORE_ID);

        $getProductDetailsQry = $this->createStub(GetProductDetailsQry::class);
        $getProductDetailsQry->method('handle')->willReturnCallback(
            fn (int $productId) => new ProductDetailsDto(
                id: $productId,
                ean: '5901234123457',
                name: 'Product Name',
                imageUrl: $productId ? 'https://img.example.com/p.jpg' : null,
                quantity: $productId ?: null
            )
        );

        $this->sut = new GetOfferDetailsQry(
            $getCurrentCustomerStoreIdQry,
            $this->offerRepository,
            $getProductDetailsQry
        );

        $this->prepareDb();
    }

    /**
     * @param class-string $expectedExceptionClass
     */
    #[Test, DataProvider('dataProviderHandle')]
    public function handle(
        int $offerId,
        string $expectedExceptionClass,
        string $expectedExceptionMessage,
        ?string $expectedProductName,
        ?QuantityLevelEnum $expectedQuantityLevel,
    ): void {
        if ($expectedExceptionClass) {
            $this->expectException($expectedExceptionClass);
            $this->expectExceptionMessageMatches('/^' . preg_quote($expectedExceptionMessage, '/') . '$/');
        }

        $result = $this->sut->handle($offerId);

        $this->assertSame($offerId, $result->id);
        $this->assertSame($expectedProductName, $result->productName);
        $this->assertSame($expectedQuantityLevel, $result->quantityLevel);
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderHandle(): array
    {
        return [
            'offer not found' => [
                'offerId' => 9999,
                'expectedExceptionClass' => AppValidationException::class,
                'expectedExceptionMessage' => 'offerId: Offer not found',
                'expectedProductName' => null,
                'expectedQuantityLevel' => null,
            ],
            'offer belongs to other store' => [
                'offerId' => 612,
                'expectedExceptionClass' => AppValidationException::class,
                'expectedExceptionMessage' => 'offerId: Requested offer belongs to other store.',
                'expectedProductName' => null,
                'expectedQuantityLevel' => null,
            ],
            'offer not visible' => [
                'offerId' => 613,
                'expectedExceptionClass' => AppValidationException::class,
                'expectedExceptionMessage' => 'visible: Requested offer is not visible.',
                'expectedProductName' => null,
                'expectedQuantityLevel' => null,
            ],
            'offer has no productId' => [
                'offerId' => 614,
                'expectedExceptionClass' => AppValidationException::class,
                'expectedExceptionMessage' => 'productId: Requested offer is for unknown product.',
                'expectedProductName' => null,
                'expectedQuantityLevel' => null,
            ],
            'success - uses offer productName' => [
                'offerId' => 610,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expectedProductName' => 'Offer Product Name',
                'expectedQuantityLevel' => QuantityLevelEnum::AVAILABLE,
            ],
            'success - falls back to product name when offer name is null' => [
                'offerId' => 611,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expectedProductName' => 'Product Name',
                'expectedQuantityLevel' => QuantityLevelEnum::AVAILABLE,
            ],
            'success - quantity level available low' => [
                'offerId' => 615,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expectedProductName' => 'Low Stock',
                'expectedQuantityLevel' => QuantityLevelEnum::AVAILABLE_LOW,
            ],
            'success - quantity level unknown' => [
                'offerId' => 616,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expectedProductName' => 'Out of Stock',
                'expectedQuantityLevel' => QuantityLevelEnum::UNKNOWN,
            ],
        ];
    }

    private function prepareDb(): void
    {
        // productId is reused as the quantity value by the stub (quantity = productId)
        $this->offerRepository->saveWithId(Offer::factory(storeId: self::STORE_ID, externalId: 'EXT-610', productEan: '5901234123457',
            productName: 'Offer Product Name', price: 1000, lowestPrice: 900, visible: true, productId: 5000, id: 610));
        $this->offerRepository->saveWithId(Offer::factory(storeId: self::STORE_ID, externalId: 'EXT-611', productEan: '5901234123458',
            productName: null, price: 800, lowestPrice: null, visible: true, productId: 5000, id: 611));
        $this->offerRepository->saveWithId(Offer::factory(storeId: 99, externalId: 'EXT-612', productEan: '5901234123459',
            productName: 'Other Store', price: 500, lowestPrice: null, visible: true, productId: 5000, id: 612));
        $this->offerRepository->saveWithId(Offer::factory(storeId: self::STORE_ID, externalId: 'EXT-613', productEan: '5901234123460',
            productName: 'Hidden', price: 500, lowestPrice: null, visible: false, productId: 5000, id: 613));
        $this->offerRepository->saveWithId(Offer::factory(storeId: self::STORE_ID, externalId: 'EXT-614', productEan: '5901234123461',
            productName: 'No Product', price: 500, lowestPrice: null, visible: true, productId: null, id: 614));
        $this->offerRepository->saveWithId(Offer::factory(storeId: self::STORE_ID, externalId: 'EXT-615', productEan: '5901234123462',
            productName: 'Low Stock', price: 500, lowestPrice: null, visible: true, productId: 1, id: 615));
        $this->offerRepository->saveWithId(Offer::factory(storeId: self::STORE_ID, externalId: 'EXT-616', productEan: '5901234123463',
            productName: 'Out of Stock', price: 500, lowestPrice: null, visible: true, productId: 0, id: 616));
        $this->offerRepository->flush();
    }
}
